import {guardianReasons} from './guardian.js?v=1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const explanations={...guardianReasons,earlier_arrival:'Earlier arrival according to the planner.',less_walking:'Less walking than the current journey.',fewer_transfers:'Fewer transfers than the current journey.',respects_deadline:'This planner result meets your arrival deadline.',avoids_disruption:'Avoids the reported cancelled trip or closed stop.',uncertainty:'Live operation is unconfirmed; keep checking the operator.',no_alternative:'No feasible alternative was found with these constraints.'};
export function guardianMarkup(a,state={},clock){
 const relevant=a.reasons.filter(r=>!['missing_live','scheduled_plan'].includes(r.code)),stale=!!state.at&&(state.key!==a.key||Date.now()-state.at>60000);
 if(state.dismissed===a.key)return '<button class="guardian-restore textbtn" data-guardian-restore>Journey Guardian</button>';
 const open=state.open||relevant.length;
 return `<div class="guardian-card guardian-${a.severity}" ${state.busy?'aria-busy="true"':''}><div class="guardian-heading"><span class="guardian-mark" aria-hidden="true">✦</span><strong>Journey Guardian</strong><span class="guardian-mode">${a.fresh?'Live + timetable':'Timetable'}</span>${open?'<button class="guardian-dismiss" data-guardian-dismiss aria-label="Dismiss Guardian recommendation">×</button>':''}</div>${open?`<p class="guardian-summary">${esc(guardianReasons[(relevant[0]||a.reasons[0])?.code]||'Your journey is being checked against the available data.')}</p>${relevant.length>1?'<ul class="guardian-evidence">'+relevant.slice(1,3).map(r=>`<li>${esc(guardianReasons[r.code])}</li>`).join('')+'</ul>':''}`:''}<small class="guardian-source">${a.alerts.length?'Official operator alert · ':''}${a.updatedAt?'Predictions updated '+esc(clock(a.updatedAt)):'Live predictions unconfirmed'} · checked ${esc(clock(a.checkedAt))}</small>${state.message?`<p class="notice" role="status">${esc(state.message)}</p>`:''}${stale?'<p class="notice">Conditions changed. Check alternatives again before choosing one.</p>':''}${state.decision&&!stale?`<div class="guardian-explanation"><span class="label">AI SUGGESTION · VERIFIED PLANNER FACTS</span>${state.decision.clarify?'<p>Please clarify your arrival time or preference for this journey.</p>':state.decision.alternativeId?`<p>AI suggests ${esc(state.decision.alternativeId.replace('option-','alternative '))}.</p>`:''}<ul>${state.decision.reasonCodes.map(r=>`<li>${esc(explanations[r])}</li>`).join('')}</ul><small>AI provider: ${esc(state.provider||'unavailable')} · ${esc(clock(state.aiAt||state.at))}${state.cached?' · cached':''}</small></div>`:''}${state.alternatives&&!stale?`<div class="guardian-alternatives">${state.alternatives.length?state.alternatives.map((x,i)=>`<article class="guardian-option"><div><span class="label">ALTERNATIVE ${i+1} · PLANNER RESULT</span><strong>Arrive ${esc(clock(x.result.arrival))}</strong><small>${Math.round(x.result.walkingMeters)} m walking · ${x.result.transfers} transfers</small></div><button class="secondary" data-guardian-choose="${x.id}">Show on map</button></article>`).join(''):'<p class="notice">No feasible alternative found. Your current journey and destination are kept.</p>'}</div>`:''}<div class="guardian-actions"><button class="secondary" data-guardian-analyze ${state.busy?'disabled':''}>${state.busy?'Checking journey…':'Compare alternatives'}</button>${state.alternatives&&!stale?`<button class="textbtn" data-guardian-explain ${state.busy?'disabled':''}>Explain with AI</button>`:''}</div>${state.alternatives&&!stale?'<p class="guardian-privacy">AI explanation sends a short transit summary, without GPS coordinates or private pin addresses. It does not run automatically.</p>':''}</div>`;
}
